      const frames: number[] = []
      const stop = { v: false }
      const loop = () => { frames.push(e.getBoundingClientRect().top - v.getBoundingClientRect().top); if (!stop.v) requestAnimationFrame(loop) }
      requestAnimationFrame(loop)
      ;(window as any).__stop = stop
      ;(window as any).__frames = frames
      return frames.length
    }, c)
    await page.mouse.wheel(0, -120)
    await page.waitForTimeout(50)
    const f = await page.evaluate(() => { (window as any).__stop.v = true; return (window as any).__frames as number[] })
    if (r === null || f.length < 2) { rows.push(`${i + 1}\tn/a`); continue }
    const total = f[f.length - 1]! - f[0]!
    let back = 0
    for (let k = 1; k < f.length; k++) if (f[k]! - f[k - 1]! < -1.5) back++
    const err = Math.abs(total - 120)
    maxErr = Math.max(maxErr, err)
    backFrames += back
    const jump = err > 2 || back > 0
    if (jump) jumps++
    rows.push(`${i + 1}\ttotal ${total.toFixed(1)}\tbackFrames ${back}\t${jump ? 'JUMP' : ''}`)
  }
  const prev = { st: await page.evaluate((s) => (document.querySelector(s) as HTMLElement).scrollTop, c.vp) }
  console.log(`## ${c.name}: ${jumps}/${STEPS} jumps, backward frames ${backFrames}, max step error ${maxErr.toFixed(1)}px, final scrollTop ${prev.st.toFixed(0)}`)
  console.log('step\tdScrollTop\tanchorMove(expect +120)\t')
  console.log(rows.join('\n'))
  await page.close()
}
await browser.close()
